__global__ void fused_pool4_sigmoid_sum_kernel(
    const float* __restrict__ conv_out,
    float* __restrict__ result,
    int N, int C, int H, int W
) {
    int n = blockIdx.x;
    int pH = H >> 2;
    int pW = W >> 2;
    int spatial = pH * pW;
